        # fallback?
        txt = HELPS.get(f"{cmd}_long", "")
    sys.stdout.write(txt)

def suggest_similar(word, candidates):
    # clap's suggestion: "some similar subcommands exist: 'pop', 'top'"
    # Use difflib to find close matches? Need to match original's logic.
    # Original for 'nope' suggested 'pop', 'top'. Let's implement simple edit distance.
    # We'll use difflib.get_close_matches with cutoff 0.6?
