    # We'll just return matches sorted? Original order: 'pop', 'top' (alphabetical? Or by similarity?)
    # For safety, sort matches? Let's keep difflib order.
    return matches

def error_unrecognized_subcommand(word):
    # error: unrecognized subcommand 'nope'\n\n  tip: some similar subcommands exist: 'pop', 'top'\n\nUsage: ...\n\nFor more information, try '--help'.\n
    # If no similar, no tip line? For 'help nope' case: error without tip, and usage without tip?
    # For top-level unknown: includes tip if similar found.
    # For 'help nope': "error: unrecognized subcommand 'nope'\n\nUsage: ...\n\nFor more information, try '--help'.\n" (no tip)
    # So help subcommand's error has no tip.
    pass

# Global state for -C and --color
class GlobalOpts:
    def __init__(self):
        self.c_paths = []
        self.color = "auto"  # auto, always, ansi, never
        self.color_explicit = False

def parse_top_args(argv):
    """
    Parse top-level args: returns (global_opts, subcommand, sub_args, error)
    Handles -C <path> (repeatable), --color <when>, --version, -h/--help
    """
    g = GlobalOpts()
    i = 0
    n = len(argv)
    subcommand = None
    sub_args = []
    # argv[0] is prog name, argv[1:] are args
    args = argv[1:]
    idx = 0
