        if a == "--":
            # end of top options? Next is subcommand?
            idx += 1
            if idx < len(args):
                subcommand = args[idx]
                sub_args = args[idx+1:]
            break
        elif a == "-C":
            # requires value
            if idx+1 >= len(args):
                # error: a value is required for '-C <path>' but none was supplied ?
                # Need to check original's error for missing -C value
                return (g, None, [], ("missing_value", "-C"))
            g.c_paths.append(args[idx+1])
            idx += 2
        elif a.startswith("-C") and len(a) > 2:
            # -C<path> attached? Does original support? Test: stg -C/tmp series ?
            # Usually clap supports -C <path> with attached? Let's assume yes: -Cfoo means -C foo
            g.c_paths.append(a[2:])
            idx += 1
        elif a == "--color":
            if idx+1 >= len(args):
                return (g, None, [], ("missing_color", None))
            val = args[idx+1]
            if val not in ("auto","always","ansi","never"):
                return (g, None, [], ("invalid_color", val))
            g.color = val
            g.color_explicit = True
            idx += 2
        elif a.startswith("--color="):
            val = a[len("--color="):]
            if val == "":
                return (g, None, [], ("missing_color", None))
            if val not in ("auto","always","ansi","never"):
                return (g, None, [], ("invalid_color", val))
            g.color = val
            g.color_explicit = True
            idx += 1
        elif a in ("-h", "--help"):
            # print top help and exit 0 (ignore rest? Original: stg --help extra? Let's test top --help with extra)
            # For top, --help should print help regardless of extra? Need to test: ./executable --help extra
            return (g, "__help__", [a], None)
        elif a == "--version":
            return (g, "__version__", [], None)
        elif a.startswith("-") and a != "-":
            # unknown top flag
            return (g, None, [], ("unexpected_arg", a))
        else:
            # subcommand
            subcommand = a
            sub_args = args[idx+1:]
            break
    return (g, subcommand, sub_args, None)

def apply_c_paths(c_paths):
    # Apply -C paths sequentially, each relative to previous if not absolute
    # Returns (final_cwd, error_msg or None)
    # Original error: "error: cannot change to `/nonexistent`: No such file or directory (os error 2)\n" exit 2
    cur = os.getcwd()
    for p in c_paths:
        # if absolute, use as is, else join with cur
        if os.path.isabs(p):
            target = p
        else:
            target = os.path.join(cur, p)
        # try to chdir? We need to actually change cwd for subsequent operations
        # But we should resolve and check existence
        try:
            # normalize?
            # Use os.chdir to test, but we need to track cur
            os.chdir(target)
            cur = os.getcwd()
        except FileNotFoundError as e:
            return (cur, f"error: cannot change to `{p}`: No such file or directory (os error 2)\n")
        except NotADirectoryError as e:
            return (cur, f"error: cannot change to `{p}`: Not a directory (os error 20)\n")
        except PermissionError as e:
            return (cur, f"error: cannot change to `{p}`: Permission denied (os error 13)\n")
        except OSError as e:
            # generic
            return (cur, f"error: cannot change to `{p}`: {e.strerror} (os error {e.errno})\n")
    return (cur, None)

