def series_resolve_single_clean(spec, full, name_to_idx, applied):
    import re
    if re.match(r"^[+-]?\d+$", spec):
        if spec.startswith("+") or spec.startswith("-"):
            try:
                off = int(spec)
            except:
                return (None, f"error: invalid patch index `{spec}`\n")
            if applied:
